import AppKit
import ProtoCore
import SwiftTerm
import SwiftUI

/// Terminal view fed only by the daemon; it never owns a process.
final class ProtoTerminalView: TerminalView {
    /// Experiment for open question A5: the daemon's emulator answers program queries,
    /// so the replies generated by this view's emulator are dropped. Keyboard input
    /// takes a different path (`TerminalViewDelegate.send`) and is not affected.
    nonisolated override func send(source: Terminal, data: ArraySlice<UInt8>) {
        let count = data.count
        DispatchQueue.main.async { AppState.shared.droppedReplyBytes += count }
    }
}

final class AppState: ObservableObject {
    static let shared = AppState()
    @Published var status = "Conectando ao daemon…"
    @Published var shortcutCount = 0
    @Published var droppedReplyBytes = 0
    @Published var receivedBytes = 0
}

/// Socket link to the prototype daemon. Frames are read on a background thread and
/// delivered on the main thread, in order.
final class DaemonLink {
    private var fd: Int32 = -1
    var onFrame: ((Frame) -> Void)?
    var onClosed: (() -> Void)?

    func connect(path: String) -> Bool {
        guard let connected = SocketIO.connect(path: path) else { return false }
        fd = connected
        let descriptor = connected
        Thread.detachNewThread { [weak self] in
            var parser = FrameParser()
            while let bytes = SocketIO.read(descriptor, timeoutMilliseconds: 1000) {
                let frames = parser.append(bytes[...])
                if !frames.isEmpty {
                    DispatchQueue.main.async {
                        for frame in frames { self?.onFrame?(frame) }
                    }
                }
            }
            DispatchQueue.main.async { self?.onClosed?() }
        }
        return true
    }

    func send(_ frame: Frame) {
        guard fd >= 0 else { return }
        SocketIO.writeAll(fd, frame.encoded())
    }
}

final class TerminalCoordinator: NSObject, TerminalViewDelegate {
    let link = DaemonLink()
    weak var view: ProtoTerminalView?
    var attached = false
    var socketPath = NSTemporaryDirectory() + "hubagent-proto.sock"
    var workingDirectory = FileManager.default.currentDirectoryPath

    func start() {
        readArguments()
        link.onFrame = { [weak self] in self?.handle($0) }
        link.onClosed = { AppState.shared.status = "Conexão com o daemon encerrada" }
        guard link.connect(path: socketPath) else {
            AppState.shared.status = "Daemon não encontrado em \(socketPath)"
            return
        }
        link.send(Frame(type: .list))
    }

    private func readArguments() {
        let arguments = CommandLine.arguments
        if let index = arguments.firstIndex(of: "--socket"), index + 1 < arguments.count {
            socketPath = arguments[index + 1]
        }
        if let index = arguments.firstIndex(of: "--cwd"), index + 1 < arguments.count {
            workingDirectory = arguments[index + 1]
        }
    }

    private var size: (columns: Int, rows: Int) {
        guard let dimensions = view?.terminalDimensions else { return (80, 24) }
        return (dimensions.cols, dimensions.rows)
    }

    private func handle(_ frame: Frame) {
        switch frame.type {
        case .sessions:
            let alive = (frame.decode([SessionInfo].self) ?? []).filter { !$0.exited }
            if let existing = alive.first {
                attach(sessionId: existing.sessionId, reused: true)
            } else {
                let request = CreateRequest(workingDirectory: workingDirectory, columns: size.columns, rows: size.rows)
                link.send(Frame.json(.create, request))
            }
        case .created:
            guard let info = frame.decode(SessionInfo.self) else { return }
            attach(sessionId: info.sessionId, reused: false)
        case .snapshot, .output:
            AppState.shared.receivedBytes += frame.payload.count
            view?.feed(byteArray: frame.payload[...])
        case .exited:
            AppState.shared.status = "Terminal encerrado (na v1 a aba fecharia aqui)"
        case .failure:
            AppState.shared.status = "Erro do daemon: \(String(decoding: frame.payload, as: UTF8.self))"
        default:
            break
        }
    }

    private func attach(sessionId: String, reused: Bool) {
        link.send(Frame.json(.attach, AttachRequest(sessionId: sessionId, columns: size.columns, rows: size.rows)))
        attached = true
        let origin = reused ? "terminal que já estava vivo, tela restaurada" : "terminal novo"
        AppState.shared.status = "Anexado: \(origin) (\(size.columns)×\(size.rows))"
        if let view { view.window?.makeFirstResponder(view) }
    }

    // MARK: TerminalViewDelegate

    func send(source: TerminalView, data: ArraySlice<UInt8>) {
        link.send(Frame(type: .input, payload: Array(data)))
    }

    func sizeChanged(source: TerminalView, newCols: Int, newRows: Int) {
        guard attached else { return }
        link.send(Frame.json(.resize, ResizeRequest(columns: newCols, rows: newRows)))
        AppState.shared.status = "Redimensionado para \(newCols)×\(newRows)"
    }

    func setTerminalTitle(source: TerminalView, title: String) {
        source.window?.title = title.isEmpty ? "Protótipo hub-agent" : title
    }

    func hostCurrentDirectoryUpdate(source: TerminalView, directory: String?) {}
    func scrolled(source: TerminalView, position: Double) {}
    func rangeChanged(source: TerminalView, startY: Int, endY: Int) {}
    func bell(source: TerminalView) { NSSound.beep() }
    func iTermContent(source: TerminalView, content: ArraySlice<UInt8>) {}

    func clipboardCopy(source: TerminalView, content: Data) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setData(content, forType: .string)
    }

    func requestOpenLink(source: TerminalView, link: String, params: [String: String]) {
        if let url = URL(string: link) { NSWorkspace.shared.open(url) }
    }
}

struct TerminalHost: NSViewRepresentable {
    func makeCoordinator() -> TerminalCoordinator { TerminalCoordinator() }

    func makeNSView(context: Context) -> ProtoTerminalView {
        let view = ProtoTerminalView(frame: NSRect(x: 0, y: 0, width: 800, height: 500), font: nil)
        view.terminalDelegate = context.coordinator
        context.coordinator.view = view
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { context.coordinator.start() }
        return view
    }

    func updateNSView(_ nsView: ProtoTerminalView, context: Context) {}
}

struct ContentView: View {
    @ObservedObject var state = AppState.shared
    @State private var selection: String? = "hub-agent"
    @State private var note = ""

    var body: some View {
        NavigationSplitView {
            List(["hub-agent", "outro-projeto"], id: \.self, selection: $selection) { Text($0) }
            TextField("Campo de teste de foco", text: $note)
                .textFieldStyle(.roundedBorder)
                .padding(8)
        } detail: {
            VStack(spacing: 0) {
                HStack {
                    Text(state.status)
                    Spacer()
                    Text("⌘T recebido: \(state.shortcutCount)×")
                }
                .font(.caption)
                .padding(6)
                TerminalHost()
            }
        }
    }
}

final class AppDelegate: NSObject, NSApplicationDelegate {
    func applicationDidFinishLaunching(_ notification: Notification) {
        NSApp.setActivationPolicy(.regular)
        NSApp.activate(ignoringOtherApps: true)
        guard ProcessInfo.processInfo.environment["PROTO_SMOKE"] != nil else { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + 4) {
            let state = AppState.shared
            logLine(
                "SMOKE status=\(state.status) receivedBytes=\(state.receivedBytes) droppedReplyBytes=\(state.droppedReplyBytes)"
            )
            NSApp.terminate(nil)
        }
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }
}

@main
struct ProtoApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) var delegate

    var body: some Scene {
        WindowGroup("Protótipo hub-agent") {
            ContentView()
        }
        .commands {
            CommandMenu("Protótipo") {
                Button("Atalho de teste") { AppState.shared.shortcutCount += 1 }
                    .keyboardShortcut("t", modifiers: .command)
            }
        }
    }
}
